import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak, monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_counts_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": None}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"c": []}) == pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize(('days', 'expected'), [(0, 0), (1, 4), (2, 6), (5, 7)])
def test_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected


def test_parser_skips_non_records_and_strips_fields():
    lines = ["", "  \t", " # ignored", " x , -3 , 1 ", "y,0,0", "z,1, "]
    assert parse_transcript_log(lines) == [
        {"id": "x", "day": -3, "flagged": True},
        {"id": "y", "day": 0, "flagged": False},
        {"id": "z", "day": 1, "flagged": None},
    ]


@pytest.mark.parametrize('bad', ['x,1', 'x,1,0,extra', 'x,today,1'])
def test_parser_reports_input_line(bad):
    with pytest.raises(ValueError, match=r'line 4\b'):
        parse_transcript_log(['# comment', 'x,1,1', ' ', bad])


def test_dedupe_keeps_last_duplicate_and_sorts_survivors():
    events = parse_transcript_log(['z,1,0', 'b,3,1', 'a,2,1', 'b,2,0'])
    assert dedupe_transcripts(events) == [events[0], events[2], events[3]]


def test_daily_counts_inclusive_and_zero_filled():
    events = parse_transcript_log(['a,0,1', 'b,1,1', 'c,1,1', 'd,2,0', 'e,4,1', 'f,5,1'])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 3) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {'a': parse_transcript_log(['a,0,1', 'b,3,0']),
              'b': parse_transcript_log(['c,3,1']), 'empty': []}
    assert monitor_summary(groups, 2) == {'rate': 0.667, 'recent': 1, 'groups': 2}
    assert monitor_summary({'empty': []}, 2) == {'rate': 0.0, 'recent': 0, 'groups': 0}


def test_group_ranking_and_rates():
    groups = {'z': [{'flagged': True}], 'a': [{'flagged': False}],
              'e': [], 'b': [{'flagged': True}]}
    assert top_flagged_groups(groups, 1) == ['b']
    assert top_flagged_groups(groups, 5) == ['b', 'z', 'a']
    assert list(flag_rate_by_group(groups).items()) == [
        ('a', 0.0), ('b', 1.0), ('e', None), ('z', 1.0),
    ]


@pytest.mark.parametrize(('counts', 'expected'), [([], 0), ([0, -1], 0), ([1, 0, 1, 2, -1, 2], 2)])
def test_streak_counts_only_consecutive_positive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
